# checar duplicados normalizados
import re
seen=set()
for n,c,u,e in rows:
    k=(n.lower(),re.sub(r'[^A-Z0-9]','',c.upper()).replace('O','0'))
    assert k not in seen,k; seen.add(k)
    assert '|' not in n+c+u+e
with open('dados_armitron.txt','w',encoding='utf-8') as f:
    for n,c,u,e in rows: f.write(f'{n}|{c}|{u}|{e}\n')
print(len(rows))
